  <h3 style="color: #00d4aa; margin-bottom: 1.5rem;">Related Intelligence</h3>
  <div style="display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 1.5rem;">
    {% for related in related_articles %}
      <a href="{{ related.get_absolute_url }}" style="background: #1a1a1a; padding: 1.5rem; text-decoration: none; color: white; border: 1px solid #333; border-radius: 8px; transition: border-color 0.3s ease;" onmouseover="this.style.borderColor='#f5a623'" onmouseout="this.style.borderColor='#333'">
        <h4 style="margin-top: 0;">{{ related.title }}</h4>
        <p style="color: #e0e0e0;">{{ related.excerpt|truncatewords:20 }}</p>
        <div style="color: #666; font-size: 0.85rem;">{{ related.category.name }} • {{ related.published_date|date:"M d, Y" }}</div>
      </a>
    {% empty %}
      <p style="color: #999;">No related articles available.</p>
    {% endfor %}
  </div>
</section>
```

