# models.py (Add index for performance)
class Article(models.Model):
    # Existing fields...
    tldr = models.TextField(blank=True, help_text="2-3 sentence summary for quick reading")
    category = models.ForeignKey('Category', on_delete=models.SET_NULL, null=True)
    published_date = models.DateTimeField(default=timezone.now)

    class Meta:
        indexes = [models.Index(fields=['category', '-published_date'])]

# views.py
from django.views.decorators.cache import cache_page

@cache_page(60 * 15)  # Cache for 15 minutes
def article_detail(request, slug):
    article = get_object_or_404(Article.objects.select_related('category', 'author'), slug=slug, is_published=True)
    related_articles = Article.objects.filter(
        category=article.category, is_published=True
    ).exclude(id=article.id).select_related('category')[:3]
    context = {
        'article': article,
        'related_articles': related_articles,
        # Other context data...
    }
    return render(request, 'articles/article_detail.html', context)
