#### 1.3 Share Row
- **Purpose:** Encourages content distribution across platforms (X, Nostr, Copy Link).
- **Design:** Teal (#00d4aa) borders with hover effects (Claude), centrally placed after content (OpenAI).
- **Functionality:** Pre-filled share text and “Copied!” state feedback (Grok & Claude) with clipboard API fallback.
- **Code:**
```html
<div class="article__share" style="display: flex; gap: 1rem; align-items: center; padding: 1.5rem; background: #0a0a0a; border-radius: 8px; margin: 2rem 0; flex-wrap: wrap; border: 1px solid #333;">
  <span class="article__share-label" style="color: #00d4aa; font-weight: 600; font-size: 0.9rem; text-transform: uppercase;">Share This Article:</span>
  <a href="{{ share_data.twitter_intent }}" target="_blank" class="article__share-btn" style="padding: 0.6rem 1.2rem; border: 2px solid #00d4aa; background: transparent; color: #00d4aa; border-radius: 6px; transition: all 0.3s ease; text-decoration: none;" onmouseover="this.style.background='#00d4aa'; this.style.color='#0a0a0a'" onmouseout="this.style.background='transparent'; this.style.color='#00d4aa'">Share on X</a>
  <button onclick="shareOnNostr()" class="article__share-btn" style="padding: 0.6rem 1.2rem; border: 2px solid #00d4aa; background: transparent; color: #00d4aa; border-radius: 6px; transition: all 0.3s ease;" onmouseover="this.style.background='#00d4aa'; this.style.color='#0a0a0a'" onmouseout="this.style.background='transparent'; this.style.color='#00d4aa'">Share on Nostr</button>
  <button onclick="copyLink(this)" class="article__share-btn" style="padding: 0.6rem 1.2rem; border: 2px solid #00d4aa; background: transparent; color: #00d4aa; border-radius: 6px; transition: all 0.3s ease;" onmouseover="this.style.background='#00d4aa'; this.style.color='#0a0a0a'" onmouseout="this.style.background='transparent'; this.style.color='#00d4aa'">Copy Link</button>
</div>

<script>
function copyLink(button) {
  if (navigator.clipboard) {
    navigator.clipboard.writeText('{{ share_data.url }}').then(() => {
      button.textContent = 'Copied!';
      button.classList.add('article__share-btn--copied');
      button.style.background = '#f5a623';
      button.style.borderColor = '#f5a623';
      button.style.color = '#0a0a0a';
      setTimeout(() => {
        button.textContent = 'Copy Link';
        button.classList.remove('article__share-btn--copied');
        button.style.background = 'transparent';
        button.style.borderColor = '#00d4aa';
        button.style.color = '#00d4aa';
      }, 2000);
    }, () => {
      alert('Failed to copy link. Please copy manually: {{ share_data.url }}');
    });
  } else {
    alert('Clipboard not supported. Please copy manually: {{ share_data.url }}');
  }
}

function shareOnNostr() {
  alert('Nostr sharing integration coming soon. Use Copy Link for now.');
}
</script>
```

